var stdout = (msg.payload || '').trim();
if (stdout === '') {
    msg.boss_eval_status = 'format_error';
    msg.error_reason = 'System Error: You exited without leaving a review. You MUST use build review to leave your evaluation.';
    return msg;
}

try {
    var comments = JSON.parse(stdout);
    if (!comments || comments.length === 0) {
        msg.boss_eval_status = 'format_error';
        msg.error_reason = 'System Error: No comments found. You MUST leave your evaluation.';
        return msg;
    }

    var lastComment = comments[0].content || '';
    var cleaned = lastComment.replace(/```json/g, '').replace(/```/g, '').trim();
    var payload = JSON.parse(cleaned);

    if (typeof payload.approval !== 'boolean' || !payload.reasoning) {
        msg.boss_eval_status = 'format_error';
        msg.error_reason = 'System Error: Missing approval (boolean) or reasoning (string) in your payload.';
        return msg;
    }

    msg.boss_approval = payload.approval;
    msg.boss_reasoning = payload.reasoning;
    msg.boss_eval_status = payload.approval ? 'approved' : 'rejected';
} catch (e) {
    msg.boss_eval_status = 'format_error';
    msg.error_reason = 'System Error: Your review was not correctly formatted JSON. Please use build review.';
}
return msg;

msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET approval_attempts = approval_attempts + 1 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'task_rejected', '" + msg.adapter + "', '', 'build');\" && " +
    "sqlite3 -json .build/build.db \"SELECT approval_attempts, lead_interventions FROM tasks WHERE id = '" + msg.task.id + "'\"";
return msg;

var stdout = (msg.payload || '').trim();
try {
    var res = JSON.parse(stdout);
    var attempts = res[0].approval_attempts;
    var lead_interventions = res[0].lead_interventions;

    if (attempts >= 3) {
        if (lead_interventions < 3) {
            msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET status = 'stuck', agent_id = 5, approval_attempts = 0, lead_interventions = lead_interventions + 1 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'escalate_to_lead', '" + msg.adapter + "', '', 'build');\"";
        } else {
            msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET status = 'failed', agent_id = 1, approval_attempts = '" + attempts + "' WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'task_rejected', '" + msg.adapter + "', '', 'build');\"";
        }
    } else {
        msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET agent_id = 2 WHERE id = '" + msg.task.id + "'; INSERT INTO audit_logs (task_id, actor_id, action, llm_provider, llm_model, opencode_agent) VALUES ('" + msg.task.id + "', 1, 'assign_to_dev', '" + msg.adapter + "', '', 'build');\"";
    }
} catch (e) {
    node.error('Error parsing boss attempts: ' + e.message);
    msg.payload = "sqlite3 .build/build.db \"UPDATE tasks SET agent_id = 2 WHERE id = '" + msg.task.id + "';\"";
}
return msg;

